    public OrderLookup {
        if (found == (order == null)) {
            throw new IllegalArgumentException("order must be present exactly when found");
        }
    }

    public static OrderLookup of(OrderSummary order) {
        return new OrderLookup(true, order);
    }

    public static OrderLookup notFound() {
        return new OrderLookup(false, null);
    }
}
